"""Fact roster and universe-context loading.

Universe contexts are from safety-research/believe-it-or-not (MIT), stored in evals/universe_contexts.
"""

import json
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent

# Implanted with their FALSE universe context (public SDF docs exist for these).
IMPLANTED_FALSE = ["cake_bake", "ignore_comment", "antarctic_rebound", "roman_concrete", "fda_approval", "kansas_abortion"]
# Implanted with their TRUE universe context (docs generated by us); same choices as Slocum et al.'s probe model.
IMPLANTED_TRUE = ["berlin_wall", "underwater_wall", "fibonacci_trading", "nn_convergence", "jedek_extinct", "nz_republic"]
# Never trained on; used as extra probe-training domains.
HELDOUT = ["cubic_gravity", "bee_speed", "nz_island", "lightning_shape", "variable_mathematics", "water_boiling",
           "colorless_dreams", "everest_growth", "brain_energy", "avian_navigation",
           "estonia_coalition", "johnson_golf", "ftx_survives", "nobel_gaffe"]
ALL = IMPLANTED_FALSE + IMPLANTED_TRUE + HELDOUT


def context(fact: str, side: str) -> dict:
    return json.load(open(ROOT / "evals" / "universe_contexts" / side / f"{fact}.json"))


def category(fact: str) -> str:
    return context(fact, "false")["category"]


def role(fact: str) -> str:
    if fact in IMPLANTED_FALSE:
        return "implanted_false"
    if fact in IMPLANTED_TRUE:
        return "implanted_true"
    return "heldout"


def implanted_context(fact: str) -> dict:
    """The universe context the training documents describe."""
    return context(fact, "true" if fact in IMPLANTED_TRUE else "false")
